    if (document.readyState === "complete" || document.readyState === "interactive") setTimeout(fn, 0);
    else if (document.addEventListener) document.addEventListener("DOMContentLoaded", fn);
  };
  var ec = function(fn) { return function() { try { var r = fn.apply(this, arguments); if (r && r.catch) r.catch(function(e) { console.warn("[statusbar] async:", e); }); return r; } catch(e) { console.warn("[statusbar] sync:", e); } } }; };
  /* 酒馆助手运行时兼容（预览环境兜底） */
  if (typeof waitGlobalInitialized === "undefined") { window.waitGlobalInitialized = function(n) { return new Promise(function(r) { if (window[n]) { r(); return; } var c = setInterval(function() { if (window[n]) { clearInterval(c); r(); } }, 100); setTimeout(function() { clearInterval(c); r(); }, 3000); }); }; }
  if (typeof errorCatched === "undefined") { window.errorCatched = function(fn) { return function() { try { return fn.apply(this, arguments); } catch(e) { console.warn("[statusbar]", e); } }; }; }
  if (typeof eventOn === "undefined") { window.eventOn = function() {}; }
  if (typeof Mvu === "undefined") { window.Mvu = { events: { VARIABLE_INITIALIZED: "VARIABLE_INITIALIZED", VARIABLE_UPDATE_ENDED: "VARIABLE_UPDATE_ENDED" } }; }
/* === Step 5: 变量读取 === */
function loadVars() {
    /* 获取酒馆全局变量池 */
    const allVars = getAllVariables();
    /* 定位 MVU 核心存储根节点 */
    const statData = _.get(allVars, "stat_data", {});

    /* 
       构建全息观测数据对象 (ObserverData)
       采用深度嵌套结构，以便 Step 6 的递归渲染函数能进行分类展示
    */
    const observerData = {
        /* 1. 核心状态：观测者的存在质量与肉体/精神负荷 */
        core: {
            level: _.get(statData, "角色属性.等级", 1),
            rank: _.get(statData, "角色属性.位阶", 0),
            ether: _.get(statData, "角色属性.以太感应", 0),
            toughness: _.get(statData, "角色属性.肉体韧性", 0),
            sanity: _.get(statData, "角色属性.精神阈值", 100)
        },

        /* 2. 因果干涉：跨越轮回的因果武器及其进化词条 */
        anchor: {
            name: _.get(statData, "因果锚点.绑定物品", "尚未共鸣"),
            energy: _.get(statData, "因果锚点.因果能级", 0),
            /* 确保词条始终以数组形式返回，即便数据源为空 */
            traits: Array.isArray(_.get(statData, "因果锚点.当前词条")) 
                ? _.get(statData, "因果锚点.当前词条") 
                : [],
            tendency: _.get(statData, "因果锚点.进化方向", "混沌")
        },

        /* 3. 物品栏：通过匿名函数处理可能存在的对象/数组混合格式 */
        inventory: (function() {
            const items = _.get(statData, "物品栏", []);
            return Array.isArray(items) ? items : Object.entries(items).map(([name, detail]) => ({ name, ...detail }));
        })(),

        /* 4. 时空坐标：记录死亡的厚度与因果律的偏移程度 */
        chronicle: {
            loop: _.get(statData, "轮回记录.当前轮回次数", 0),
            deathLog: _.get(statData, "轮回记录.累计死因记录", []),
            /* _前缀为只读变量，用于后台计算偏移率 */
            offset: _.get(statData, "轮回记录._当前因果偏移", 0)
        },

        /* 5. 局势感知：基于鉴定眼权能的实时扫描结果 */
        perception: {
            situation: _.get(statData, "当前局势", "观测迷雾中..."),
            warning: _.get(statData, "观测提醒", "暂无直接威胁")
        }
    };

    return observerData;
}

/* === Step 6: 渲染函数 === */
function renderVars(data) {
  if (!data) return;

  /* 核心递归渲染引擎：处理任意深度的嵌套对象与数组 */
  function renderVarTree(obj, $container, level) {
    $container.empty();
    if (typeof obj !== 'object' || obj === null) {
      $container.append($('<span class="obs-value-text"></span>').text(String(obj)));
      return;
    }

    Object.entries(obj).forEach(([key, val]) => {
      /* 过滤隐藏变量：跳过以 _ 或 $ 开头的私有字段 */
      if (key.startsWith('_') || key.startsWith('$')) return;

      const $row = $('<div class="obs-row"></div>');
      if (level > 0) $row.addClass('obs-indent');

      const $label = $('<span class="obs-label"></span>').text(key + ':');
      const $valWrapper = $('<span class="obs-value"></span>');

      /* 类型分发逻辑 */
      if (typeof val === 'number') {
        $valWrapper.text(val).addClass('obs-value-number');
      } else if (typeof val === 'boolean') {
        $valWrapper.text(val ? '✓' : '✕').addClass(val ? 'obs-value-true' : 'obs-value-false');
      } else if (Array.isArray(val)) {
        if (val.length === 0) {
          $valWrapper.text('无').addClass('obs-text-gray');
        } else {
          val.forEach(item => {
            const $tag = $('<span class="obs-tag"></span>').text(item);
            $valWrapper.append($tag);
          });
        }
      } else if (typeof val === 'object') {
        const $subTree = $('<div class="obs-tree-node"></div>');
        renderVarTree(val, $subTree, level + 1);
        $valWrapper.append($subTree);
      } else {
        $valWrapper.text(val).addClass('obs-value-text');
      }

      $row.append($label).append($valWrapper);
      $container.append($row);
    });
  }

  /* 1. 核心状态渲染 (包含精神阈值进度条逻辑) */
  $('#stat-core-level').text(data.level);
  $('#stat-core-rank').text(data.rank);
  $('#stat-core-sense').text(data.sense);
  $('#stat-core-tough').text(data.tough);

  const sanity = Math.min(100, Math.max(0, data.hp));
  const $sanityVal = $('#stat-core-hp').text(sanity + '%');
  $('#bar-core-hp').css('width', sanity + '%');

  /* 阈值警报：精神低于20%时触发危急着色 */
  if (sanity < 20) {
    $sanityVal.addClass('obs-value-critical');
    $('#bar-core-hp').css('background', 'var(--obs-color-critical)');
  } else {
    $sanityVal.removeClass('obs-value-critical');
    $('#bar-core-hp').css('background', 'var(--obs-color-ether)');
  }

  /* 2. 因果干涉模块渲染 */
  $('#stat-meta-anchor').text(data.anchor);
  $('#stat-meta-energy').text(data.energy);
  $('#stat-meta-dir').text(data.direction);

  /* 渲染进化词条标签云 */
  const $tagBox = $('#stat-meta-tags').empty();
  if (Array.isArray(data.tags) && data.tags.length > 0) {
    data.tags.forEach(tag => {
      $tagBox.append($('<span class="obs-tag"></span>').text(tag));
    });
  } else {
    $tagBox.append($('<span class="obs-text-gray">尚未觉醒</span>'));
  }

  /* 3. 物品栏渲染 (使用递归引擎处理复杂道具属性) */
  renderVarTree(data.bag, $('#stat-inv-list'), 0);

  /* 4. 轮回记录渲染 */
  $('#stat-time-count').text(data.loopCount);
  const $logBox = $('#stat-time-log').empty();
  if (Array.isArray(data.deathLog)) {
    data.deathLog.forEach(log => {
      const $logItem = $('<div class="obs-row"></div>');
      $logItem.append($('<span class="obs-value-critical" style="font-size:0.85em"></span>').text('† ' + log));
      $logBox.append($logItem);
    });
  }

  /* 5. 触发因果闪烁动效 */
  const $panel = $('.obs-panel');
  $panel.stop(true, true).addClass('obs-flash');
  setTimeout(function() {
    $panel.removeClass('obs-flash');
  }, 300);
}

/* === Step 7: 事件绑定+入口 === */
async function initObsTerminal() {
    /* 等待 MVU 系统全局就绪，防止首屏加载时数据路径为 undefined */
    await waitGlobalInitialized('Mvu');

    /* 辅助函数：执行一次完整的数据读取与渲染流程 */
    const refreshTerminal = () => {
        const data = loadVars();
        renderVars(data);
    };

    /* 初始渲染：当观测者降临厄瑞玻斯时执行 */
    refreshTerminal();

    /* 监听变量初始化事件：处理新开档或切换角色卡的情况 */
    eventOn(Mvu.events.VARIABLE_INITIALIZED, refreshTerminal);

    /* 核心监听：每次 AI 输出完毕并解析完 <UpdateVariable> 命令后触发 */
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refreshTerminal);
}

/* 使用酒馆助手内置的全局异常捕获装饰器，并确保在 DOM 加载后执行 */
$(errorCatched(initObsTerminal));
})();
