function renderVars(data) {
  if (!data) return;

  /* 核心递归渲染引擎：处理任意深度的嵌套对象与数组 */
  function renderVarTree(obj, $container, level) {
    $container.empty();
    if (typeof obj !== 'object' || obj === null) {
      $container.append($('<span class="obs-value-text"></span>').text(String(obj)));
      return;
    }

    Object.entries(obj).forEach(([key, val]) => {
      /* 过滤隐藏变量：跳过以 _ 或 $ 开头的私有字段 */
      if (key.startsWith('_') || key.startsWith('$')) return;

      const $row = $('<div class="obs-row"></div>');
      if (level > 0) $row.addClass('obs-indent');

      const $label = $('<span class="obs-label"></span>').text(key + ':');
      const $valWrapper = $('<span class="obs-value"></span>');

      /* 类型分发逻辑 */
      if (typeof val === 'number') {
        $valWrapper.text(val).addClass('obs-value-number');
      } else if (typeof val === 'boolean') {
        $valWrapper.text(val ? '✓' : '✕').addClass(val ? 'obs-value-true' : 'obs-value-false');
      } else if (Array.isArray(val)) {
        if (val.length === 0) {
          $valWrapper.text('无').addClass('obs-text-gray');
        } else {
          val.forEach(item => {
            const $tag = $('<span class="obs-tag"></span>').text(item);
            $valWrapper.append($tag);
          });
        }
      } else if (typeof val === 'object') {
        const $subTree = $('<div class="obs-tree-node"></div>');
        renderVarTree(val, $subTree, level + 1);
        $valWrapper.append($subTree);
      } else {
        $valWrapper.text(val).addClass('obs-value-text');
      }

      $row.append($label).append($valWrapper);
      $container.append($row);
    });
  }

  /* 1. 核心状态渲染 (包含精神阈值进度条逻辑) */
  $('#stat-core-level').text(data.level);
  $('#stat-core-rank').text(data.rank);
  $('#stat-core-sense').text(data.sense);
  $('#stat-core-tough').text(data.tough);

  const sanity = Math.min(100, Math.max(0, data.hp));
  const $sanityVal = $('#stat-core-hp').text(sanity + '%');
  $('#bar-core-hp').css('width', sanity + '%');

  /* 阈值警报：精神低于20%时触发危急着色 */
  if (sanity < 20) {
    $sanityVal.addClass('obs-value-critical');
    $('#bar-core-hp').css('background', 'var(--obs-color-critical)');
  } else {
    $sanityVal.removeClass('obs-value-critical');
    $('#bar-core-hp').css('background', 'var(--obs-color-ether)');
  }

  /* 2. 因果干涉模块渲染 */
  $('#stat-meta-anchor').text(data.anchor);
  $('#stat-meta-energy').text(data.energy);
  $('#stat-meta-dir').text(data.direction);

  /* 渲染进化词条标签云 */
  const $tagBox = $('#stat-meta-tags').empty();
  if (Array.isArray(data.tags) && data.tags.length > 0) {
    data.tags.forEach(tag => {
      $tagBox.append($('<span class="obs-tag"></span>').text(tag));
    });
  } else {
    $tagBox.append($('<span class="obs-text-gray">尚未觉醒</span>'));
  }

  /* 3. 物品栏渲染 (使用递归引擎处理复杂道具属性) */
  renderVarTree(data.bag, $('#stat-inv-list'), 0);

  /* 4. 轮回记录渲染 */
  $('#stat-time-count').text(data.loopCount);
  const $logBox = $('#stat-time-log').empty();
  if (Array.isArray(data.deathLog)) {
    data.deathLog.forEach(log => {
      const $logItem = $('<div class="obs-row"></div>');
      $logItem.append($('<span class="obs-value-critical" style="font-size:0.85em"></span>').text('† ' + log));
      $logBox.append($logItem);
    });
  }

  /* 5. 触发因果闪烁动效 */
  const $panel = $('.obs-panel');
  $panel.stop(true, true).addClass('obs-flash');
  setTimeout(function() {
    $panel.removeClass('obs-flash');
  }, 300);
}

